{"implementation": "def solve(case):
    nodes = case['nodes']
    core = case['core_distance']
    dist_list = case['distances']
    dist = {}
    for a, b, d in dist_list:
        key = (min(a, b), max(a, b))
        if key not in dist:
            dist[key] = d
    n = len(nodes)
    for node in nodes:
        if node not in core:
            raise ValueError(f'Missing core distance for {node}')
    edges = []
    for i in range(n):
        u = nodes[i]
        for j in range(i+1, n):
            v = nodes[j]
            key = (u, v) if u < v else (v, u)
            d = dist.get(key)
            if d is None:
                raise ValueError(f'Missing distance between {u} and {v}')
            mr = max(core[u], core[v], d)
            edges.append((mr, u, v))
    edges.sort(key=lambda x: (x[0], x[1], x[2]))
    parent = {u: u for u in nodes}
    rank = {u: 0 for u in nodes}
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True
    mst_edges = []
    total_weight = 0.0
    for mr, u, v in edges:
        if union(u, v):
            mst_edges.append([u, v, mr])
            total_weight += mr
            if len(mst_edges) == n - 1:
                break
    if len(mst_edges) != n - 1:
        raise ValueError('Graph is not connected, cannot form MST')
    return {'mst_edges': mst_edges, 'total_weight': total_weight}"}
